css:
.cat-check,.cat-radio{display:inline-flex;align-items:center;gap:8px;font:400 var(--cat-font-size-base) var(--cat-font-family-ui);color:var(--cat-color-ink-hi);cursor:pointer;user-select:none}
.cat-check input,.cat-radio input{position:absolute;opacity:0;width:0;height:0}
.cat-check .box{width:17px;height:17px;border-radius:var(--cat-size-radius-xs);border:1.5px solid var(--cat-color-stroke-input);background:rgba(255,255,255,.6);display:grid;place-items:center;transition:all var(--cat-motion-fast) var(--cat-motion-ease-out)}
.cat-check .box::after{content:"";width:9px;height:5px;border-left:2px solid #fff;border-bottom:2px solid #fff;transform:rotate(-45deg) translate(1px,-1px) scale(0);transition:transform var(--cat-motion-fast) var(--cat-motion-spring)}
.cat-check input:checked+.box{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));border-color:transparent}
.cat-check input:checked+.box::after{transform:rotate(-45deg) translate(1px,-1px) scale(1)}
.cat-radio .box{border-radius:50%}
.cat-radio .box::after{content:"";width:8px;height:8px;border-radius:50%;background:#fff;transform:scale(0);transition:transform var(--cat-motion-fast) var(--cat-motion-spring)}
.cat-radio input:checked+.box{background:var(--cat-semantic-accent-dynamic,var(--cat-color-accent-base));border-color:transparent}
.cat-radio input:checked+.box::after{transform:scale(1)}
.cat-check input:focus-visible+.box,.cat-radio input:focus-visible+.box{box-shadow:0 0 0 var(--cat-size-border-focus-ring) var(--cat-semantic-accent-ring)}
.cat-check input:disabled~*,.cat-radio input:disabled~*{opacity:.5}
